// Minimal Meteor Defense game
// Canvas with id "game" assumed in the HTML

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) {
    console.error('Canvas "game" not found');
    return;
  }
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  // Ship definition
  const ship = {
    w: 40,
    h: 20,
    x: width / 2 - 20,
    y: height - 30,
    speed: 6,
    color: '#0f0',
  };

  // Input handling
  const keys = {};
  document.addEventListener('keydown', e => {
    keys[e.code] = true;
    if (e.code === 'Space') fire();
  });
  document.addEventListener('keyup', e => (keys[e.code] = false));
  canvas.addEventListener('click', fire);

  function fire() {
    projectiles.push({ x: ship.x + ship.w / 2, y: ship.y, r: 4, speed: 8 });
  }

  const projectiles = [];
  const meteors = [];
  let score = 0;
  let gameOver = false;

  // Spawn meteors
  function spawnMeteor() {
    const radius = 12 + Math.random() * 12;
    meteors.push({
      x: Math.random() * (width - 2 * radius) + radius,
      y: -radius,
      r: radius,
      speed: 1 + Math.random() * 2,
      color: '#f44',
    });
  }
  setInterval(spawnMeteor, 1000);

  function update() {
    if (gameOver) return;
    // Move ship
    if (keys['ArrowLeft']) ship.x -= ship.speed;
    if (keys['ArrowRight']) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(width - ship.w, ship.x));

    // Update projectiles
    for (let i = projectiles.length - 1; i >= 0; i--) {
      const p = projectiles[i];
      p.y -= p.speed;
      if (p.y < 0) projectiles.splice(i, 1);
    }

    // Update meteors
    for (let i = meteors.length - 1; i >= 0; i--) {
      const m = meteors[i];
      m.y += m.speed;
      // Collision with ship (simple AABB vs circle)
      const shipRect = { x: ship.x, y: ship.y, w: ship.w, h: ship.h };
      const distX = Math.abs(m.x - (shipRect.x + shipRect.w / 2));
      const distY = Math.abs(m.y - (shipRect.y + shipRect.h / 2));
      if (distX > shipRect.w / 2 + m.r || distY > shipRect.h / 2 + m.r) {
        // no collision
      } else {
        gameOver = true;
        break;
      }
      // Collision with projectiles
      for (let j = projectiles.length - 1; j >= 0; j--) {
        const p = projectiles[j];
        const dx = m.x - p.x;
        const dy = m.y - p.y;
        if (dx * dx + dy * dy < (m.r + p.r) * (m.r + p.r)) {
          meteors.splice(i, 1);
          projectiles.splice(j, 1);
          score++;
          break;
        }
      }
      // Remove if out of bounds
      if (m.y - m.r > height) meteors.splice(i, 1);
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Ship
    ctx.fillStyle = ship.color;
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // Projectiles
    ctx.fillStyle = '#ff0';
    projectiles.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // Meteors
    meteors.forEach(m => {
      ctx.fillStyle = m.color;
      ctx.beginPath();
      ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // Score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#f00';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', width / 2 - 60, height / 2);
    }
  }

  function loop() {
    if (!gameOver) update();
    draw();
    requestAnimationFrame(loop);
  }
  loop();
})();
